'use strict';
function miniSvg(type, info){
 if(!info)return '<div class="auto-unavailable">'+(type==='scatter'?'Scatter needs two numeric columns.':'No suitable values for this chart.')+'</div>';
 const W=360,H=190,L=38,R=15,T=15,B=32,w=W-L-R,h=H-T-B;
 let shapes='',labels='';
 if(type==='histogram'){
  const max=Math.max(...info.counts,1),bw=w/info.counts.length;
  shapes=info.counts.map((n,i)=>`<rect x="${L+i*bw+1}" y="${T+h-n/max*h}" width="${bw-2}" height="${n/max*h}" rx="2" fill="#9b87e2"><title>${esc(info.edges[i].toFixed(2))}–${esc(info.edges[i+1].toFixed(2))}: ${n} rows</title></rect>`).join('');
  labels=`<text x="${L}" y="${H-13}">${info.edges[0].toFixed(1)}</text><text x="${W-R}" y="${H-13}" text-anchor="end">${info.edges.at(-1).toFixed(1)}</text>`;
 }else if(type==='scatter'){
  const xs=info.points.map(p=>p[0]),ys=info.points.map(p=>p[1]);const xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);
  shapes=info.points.map(([x,y])=>`<circle cx="${L+(x-xmin)/(xmax-xmin||1)*w}" cy="${T+h-(y-ymin)/(ymax-ymin||1)*h}" r="2.5" fill="#8673d0" opacity=".6"><title>${esc(info.x)}: ${x}, ${esc(info.y)}: ${y}</title></circle>`).join('');
  labels=`<text x="${L}" y="${H-13}">${xmin.toFixed(1)}</text><text x="${W-R}" y="${H-13}" text-anchor="end">${xmax.toFixed(1)}</text>`;
 }else{
  const max=Math.max(...info.counts,1),bh=h/Math.max(1,info.counts.length);shapes=info.counts.map((n,i)=>`<rect x="95" y="${T+i*bh}" width="${n/max*(W-115)}" height="${Math.max(3,bh-4)}" rx="2" fill="#75baa7"><title>${esc(info.labels[i])}: ${n} rows</title></rect><text x="88" y="${T+i*bh+Math.max(8,bh/2)}" text-anchor="end">${esc(info.labels[i].slice(0,14))}</text>`).join('');
 }
 return `<svg class="auto-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(type)} of actual dataset values"><path d="M${L} ${T}V${T+h}H${W-R}" stroke="#eceaf3" fill="none"/>${shapes}${labels}</svg>`;
}
function visualDashboard(){const d=state.dataset,v=d.visuals;return `<section class="panel automatic-overview">${panelHead('Your CSV, visualized automatically',`${esc(d.name)} · ${num(v.sample_rows)} ${v.sampled?'randomly sampled':'total'} rows. Missing numeric points omitted; hover marks for values.`,button('Advanced import settings','settings','import_advanced'))}<div class="automatic-grid">${[['histogram','Histogram',v.histogram,v.histogram?.column],['scatter','Scatter plot',v.scatter,v.scatter?`${v.scatter.x} × ${v.scatter.y}`:'Select numeric columns'],['bar','Category bar chart',v.bar,v.bar?.column]].map(([type,label,info,sub])=>`<div class="automatic-chart"><h3>${label}</h3><p>${esc(sub||'No suitable column')}</p>${miniSvg(type,info)}</div>`).join('')}</div><div class="visual-selectors"><label>Numeric X<select id="auto-x">${options(v.numeric_columns,v.histogram?.column)}</select></label><label>Numeric Y<select id="auto-y">${options(v.numeric_columns,v.scatter?.y)}</select></label><label>Bar chart column<select id="auto-category">${options(v.category_columns,v.bar?.column)}</select></label>${button('Update charts','chart','refresh_visuals')}<span class="hint">Top 10 category frequencies</span></div></section>`;}
function planOverview(){const g=state.guidance;return `<section class="panel guidance-overview">${panelHead('What should you do next?','Suggestions are based on this CSV. Nothing is changed without your review.',pageButton('Review preprocessing','shield','analyzer',true))}<div class="panel-body"><div class="guide-next"><b>1 · Review the data</b><b>2 · Preview preprocessing</b><b>3 · Choose target & compare</b></div><p class="paragraph">${esc(g.next_step)}</p>${g.warnings.slice(0,2).map(w=>`<div class="warning">${esc(w)}</div>`).join('')}<div class="dataset-chips">${g.steps.slice(0,5).map(s=>`<span class="tag ${s.stage==='training'?'green':'purple'}">${esc(s.title)}</span>`).join('')}</div></div></section>`;}
function preprocessingGuide(){const g=state.guidance;return `<section class="panel guidance-overview">${panelHead('Your preprocessing plan','Review the reason, preview changes, and apply only what fits your dataset.')}<div class="panel-body">${g.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('')}<div class="plan-steps">${g.steps.map((s,i)=>`<article class="plan-step"><span class="plan-number">${i+1}</span><div><h3>${esc(s.title)} <span class="tag ${s.stage==='training'?'green':'purple'}">${s.stage==='training'?'Automatic during training':'Review first'}</span></h3><div class="step-columns">${esc(s.columns.join(', ')||'All rows')}</div><p>${esc(s.reason)}</p><small>${esc(s.risk)}</small></div>${s.operation?`<button class="button small" data-suggestion="${i}">${icon('search')}Preview</button>`:''}</article>`).join('')||'<p class="paragraph">No specific cleaning operation is indicated by the current rules.</p>'}</div></div></section>`;}
function methodGuide(){const g=state.guidance;return `<section class="panel guidance-overview">${panelHead('Which method fits this dataset?','Choose your prediction target and task below. These are candidates, not promises of performance.')}<div class="panel-body"><div class="form-row"><div class="form-field"><label>Target / outcome you want to predict</label><select data-config="target">${options(['',...state.dataset.fields.map(f=>f.name)],state.target)}</select></div><div class="form-field"><label>Prediction task</label><select id="task-choice">${options(['classification','regression'],g.task)}</select><p class="hint">Classification: category / class. Regression: numeric amount.</p></div></div>${g.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('')}<div class="method-cards">${g.algorithms.map(a=>`<article><h3>${esc(a.algorithm)}</h3><p>${esc(a.why)}</p><p class="dataset-fit">${esc(a.dataset_fit)}</p><small>${esc(a.tradeoff)}</small></article>`).join('')}</div></div></section>`;}
function comparisonReason(){const e=state.comparison_explanation;if(!e.leaders.length)return '';return `<section class="comparison-explanation"><span class="tag purple">Observed leader${e.leaders.length>1?'s':''} · ${esc(e.metric)}</span><h3>${esc(e.leaders.join(' / '))}</h3><p>${esc(e.summary)}</p><div class="reason-list">${e.rows.map(r=>`<article><b>${esc(r.algorithm)}</b><span>${r.score.toFixed(4)} · gap ${r.difference.toFixed(4)}</span><p>${esc(r.why)}</p><small>${esc(r.tradeoff)}</small></article>`).join('')}</div><div class="warning">${esc(e.caution)}</div></section>`;}
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',database:'M20 6c0 2.2-16 2.2-16 0s16-2.2 16 0ZM4 6v12c0 3 16 3 16 0V6M4 12c0 3 16 3 16 0',flow:'M5 4h6v6H5zM13 14h6v6h-6zM8 10v7h5M11 7h5v7',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3ZM8 12l3 3 5-6',chart:'M4 3v17h17M8 16v-5M13 16V7M18 16v-8',brain:'M9 4c-4-2-7 4-4 6-4 3-2 8 2 8 0 3 5 3 5 0V6c0-3-3-4-3-2ZM15 4c4-2 7 4 4 6 4 3 2 8-2 8 0 3-5 3-5 0M7 8l2 2M5 14h4M17 8l-2 2M19 14h-4',history:'M4 7v-4M4 7h4M4 7a9 9 0 1 1-1 8M12 7v5l3 2',box:'m12 3 9 5-9 5-9-5 9-5ZM3 8v9l9 5 9-5V8M12 13v9',report:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',settings:'M10 3h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3 3-3ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',help:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18ZM9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01',upload:'M12 16V3M7 8l5-5 5 5M4 15v5h16v-5',folder:'M3 6h7l2 2h9v12H3z',plus:'M12 5v14M5 12h14',arrow:'M4 12h15M14 7l5 5-5 5',chevron:'m9 5 7 7-7 7',play:'m8 4 12 8-12 8V4Z',check:'m5 12 4 4L19 6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',table:'M3 4h18v16H3zM3 9h18M9 9v11',download:'M12 3v13M7 11l5 5 5-5M4 17v4h16v-4',undo:'M8 4 3 9l5 5M3 9h10a7 7 0 0 1 7 7',redo:'m16 4 5 5-5 5M21 9H11a7 7 0 0 0-7 7',close:'m6 6 12 12M6 18 18 6',search:'M16 16l5 5M18 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z',columns:'M3 4h18v16H3zM9 4v16M15 4v16',filter:'M3 4h18l-7 8v7l-4 2v-9L3 4Z',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',minus:'M5 12h14',fit:'M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6',code:'m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18',file:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5',cpu:'M7 7h10v10H7zM3 9h4M3 15h4M17 9h4M17 15h4M9 3v4M15 3v4M9 17v4M15 17v4'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const esc=(value)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n)=>Number(n||0).toLocaleString();
const navigation=[['home','grid','Overview'],['workflow','flow','Workflow Studio'],['data','database','Dataset Explorer'],['analyzer','shield','Smart Analyzer'],['analytics','chart','Visual Analytics'],['models','brain','Model Lab'],['safety','shield','Safety Advisor'],['impact','layers','Impact Lab'],['reliability','chart','Reliability'],['errors','search','Error Detective'],['researchpack','code','Research Pack'],['deep','layers','Deep Learning'],['history','history','Experiment History'],['predictions','box','Models & Predictions'],['reports','report','Reports']];
let state=null,bridge=null,lastSource=null;
const view={page:'home',issue:0,severity:'All findings',dataTab:'preview',search:'',chartType:'Histogram',chartX:'',chartY:'',selectedNode:null,connecting:null,zoom:1,graphHistory:[],experiment:null};
const content=document.querySelector('#content');
function button(label,ic,action,primary=false,disabled=false,extra=''){return `<button class="button ${primary?'primary':''}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${ic?icon(ic):''}${label}</button>`;}
function pageButton(label,ic,page,primary=false){return `<button class="button ${primary?'primary':''}" data-page="${page}" ${page==='deep'?'disabled title="Deep Learning is not implemented in this release"':''}>${icon(ic)}${label}${page==='deep'?'<small class="unavailable-badge">Unavailable</small>':''}</button>`;}
function cmd(action,data={}){if(bridge)bridge.command(action,JSON.stringify(data));}
function toast(message,kind='success'){const el=document.querySelector('#toast');el.textContent=message;el.className=`toast show ${kind}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),6500);}
function options(items,current){return items.map(i=>`<option ${i===current?'selected':''} value="${esc(i)}">${esc(i||'Select the outcome to predict…')}</option>`).join('');}
function title(heading,sub,actions=''){return `<div class="page-title"><div><h1>${heading}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function empty(ic,heading,sub,action='',compact=false){return `<div class="empty-state ${compact?'compact':''}"><span class="empty-icon">${icon(ic)}</span><h3>${heading}</h3><p>${sub}</p>${action}</div>`;}
function panelHead(heading,sub='',extra=''){return `<div class="panel-head"><div><h2>${heading}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`;}
function stat(label,value,note,ic,color=''){return `<div class="stat-card"><div class="stat-top">${label}<span class="stat-icon ${color}">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${note}</div></div>`;}
function noData(heading='A little data goes a long way.'){return `<div class="panel">${empty('database',heading,'Import a CSV to explore your data and unlock your local ML tools.',button('Import dataset','upload','import',true))}</div>`;}
function renderNav(){document.querySelector('#navigation').innerHTML=navigation.map(([page,ic,label])=>`<button class="nav-item ${view.page===page?'active':''}" data-page="${page}" ${page==='deep'?'disabled title="Deep Learning is not implemented in this release"':''}>${icon(ic)}${label}${page==='deep'?'<small class="unavailable-badge">Unavailable</small>':''}</button>`).join('');document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));document.querySelector('.sidebar-bottom [data-page]').classList.toggle('active',view.page==='settings');}
function navigate(page){view.page=page;view.experiment=null;render();window.scrollTo(0,0);}
function render(){if(!state)return;const canvas=document.querySelector('.canvas-host');const scroll=canvas?[canvas.scrollLeft,canvas.scrollTop]:[0,0];renderNav();document.querySelector('#breadcrumb-current').textContent=navigation.find(n=>n[0]===view.page)?.[2]||'Settings & help';document.querySelector('#app-version').textContent=state.version;document.querySelector('#status-text').textContent=state.status;document.querySelector('#dataset-status').textContent=state.dataset?`${state.dataset.name} · ${num(state.dataset.rows)} rows · v${state.dataset.version}`:'No dataset loaded';const pages={safety:renderSafety,impact:renderImpact,reliability:renderReliability,errors:renderErrors,researchpack:renderResearchPack,home:renderHome,workflow:renderWorkflow,data:renderData,analyzer:renderAnalyzer,analytics:renderAnalytics,models:renderModels,history:renderHistory,predictions:renderPredictions,reports:renderReports,settings:renderSettings,deep:renderDeep,...(window.studioPages||{})};content.innerHTML=(state.busy?`<div class="busy-strip"><span class="spinner"></span>${esc(state.status)}<span style="margin-left:auto">Running locally</span></div>`:'')+(pages[view.page]||renderHome)();document.querySelector('.progress-bar')?.remove();if(state.busy){const strip=document.createElement('div');strip.className='progress-bar';document.body.append(strip);}renderModal();const host=document.querySelector('.canvas-host');if(host){host.scrollLeft=scroll[0];host.scrollTop=scroll[1];}document.body.dataset.ready='true';}
function renderHome(){const d=state.dataset;const hero=`<section class="hero"><div class="hero-copy"><div class="eyebrow">LESS CODE. MORE DISCOVERY.</div><h2>Your next discovery<br>starts here.</h2><p>From raw data to meaningful results. Build, explore, and experiment in a workspace that's entirely yours.</p>${button(d?'Explore your dataset':'Import your first dataset','plus',d?'go_data':'import',true)}</div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 550 220"><defs><linearGradient id="node-fill" x2="1" y2="1"><stop stop-color="#51466d"/><stop offset="1" stop-color="#332e4d"/></linearGradient></defs><g fill="none" stroke="#9981ce" stroke-width="1.2" opacity=".45"><path d="M95 110H220Q245 110 245 80V60H340M245 110v50h95M390 60h60v50h45M390 160h60v-50"/><path d="M0 110H45" stroke-dasharray="4 5"/></g><g fill="url(#node-fill)" stroke="#8f79b3" stroke-opacity=".5"><rect x="45" y="77" width="68" height="68" rx="16" transform="rotate(-10 79 111)"/><rect x="194" y="77" width="68" height="68" rx="16"/><rect x="320" y="25" width="68" height="68" rx="16" transform="rotate(10 354 59)"/><rect x="320" y="130" width="68" height="68" rx="16" transform="rotate(-7 354 164)"/></g><g fill="none" stroke="#c8b9ec" stroke-width="1.4"><ellipse cx="79" cy="101" rx="13" ry="5"/><path d="M66 101v17c0 7 26 7 26 0v-17M66 110c0 7 26 7 26 0M218 101l10-5 10 5-10 5-10-5ZM218 108l10 5 10-5M218 115l10 5 10-5M346 50v19M354 44v25M362 55v14M343 169l7 5 13-17"/></g><g fill="#b6a2e2"><circle cx="245" cy="110" r="3"/><circle cx="450" cy="110" r="3"/><circle cx="495" cy="110" r="4"/></g></svg></div><div class="hero-tag"><span class="online-dot"></span> BUILT FOR YOUR CURIOSITY</div></section>`;
const stats=`<div class="stats-grid">${stat('Active dataset',d?'01':'00',d?esc(d.name):'Ready for your first import','database')}${stat('Experiments',num(state.experiment_count),'Stored on this computer','brain','blue')}${stat('Quality findings',num(state.issues.length),d?'Evidence-based analysis':'Import data to analyze','shield','orange')}${stat('Session model',state.model?'01':'00',state.model?'Trained and ready to predict':'Your next experiment awaits','box','green')}</div>`;
const dataset=d?`<div class="panel-body"><div class="file-card"><span class="file-icon">${icon('file')}</span><div class="file-meta"><h3>${esc(d.name)}</h3><p>${num(d.rows)} rows · ${d.columns} columns · ${(d.bytes/1048576).toFixed(2)} MB</p></div><span class="tag green">CSV</span></div>${d.distribution?`<div class="mini-chart" aria-label="Actual distribution of ${esc(d.distribution.column)}">${d.distribution.values.map(v=>`<i style="height:${Math.max(2,v/Math.max(...d.distribution.values,1)*100)}%" title="${num(v)} rows"></i>`).join('')}</div><div class="chart-label"><span>${esc(d.distribution.column)} distribution</span><span>All ${num(d.rows)} rows</span></div>`:`<p class="hint">${d.fields.filter(f=>!['int64','float64'].includes(f.type)).length} nonnumeric columns · Explore the schema for more.</p>`}</div>`:empty('database','Your data, your starting point','Bring a CSV dataset into your workspace to get started.',button('Browse files','folder','import'),true);
const history=state.experiments.slice(0,3).map(e=>`<div class="activity-row"><span class="activity-dot"></span><div><h3>${esc(e.algorithm)}</h3><p>${esc(e.created)} UTC</p></div><span class="tag green">Completed</span></div>`).join('');
return title('Workspace overview','A clear space for your next big idea.',button('Open project','folder','open')+button('Import dataset','plus','import',true))+(d?visualDashboard()+planOverview():hero)+stats+`<div class="grid-two"><section class="panel">${panelHead('Your dataset','A closer look at what you’re working with.',`<button class="text-link" data-page="data">View explorer ${icon('arrow')}</button>`)}${dataset}</section><section class="panel">${panelHead('Recent activity','Experiments you’ve run, all in one place.',`<button class="text-link" data-page="history">View all</button>`)}${history?`<div class="panel-body">${history}</div>`:empty('history','A fresh beginning','Your completed experiments will appear here. Time to try something.',pageButton('Go to Model Lab','arrow','models'),true)}</section></div><div class="section-title">Make something meaningful<span class="subtle" style="font-size:10px;font-weight:400">A few good places to start</span></div><div class="quick-grid">${[['analyzer','shield','Understand your data','Find patterns. Spot quality issues.'],['workflow','flow','Connect the dots','Build a visual ML pipeline.'],['models','brain','Put a model to work','Train locally. Learn from results.']].map(([p,ic,h,t])=>`<button class="quick-card" data-page="${p}"><span class="stat-icon">${icon(ic)}</span><div><h3>${h}</h3><p>${t}</p></div><span class="arrow">↗</span></button>`).join('')}</div>`;}
function table(data,fields=[],limit=100,compare=null){return `<table><thead><tr><th>#</th>${data.columns.map(c=>`<th>${esc(c)}${fields.find(f=>f.name===c)?`<small>${esc(fields.find(f=>f.name===c).type)}</small>`:''}</th>`).join('')}</tr></thead><tbody>${data.data.slice(0,limit).map((row,i)=>`<tr><td class="index">${i+1}</td>${row.map((v,j)=>`<td class="${compare&&v!==compare.data[i]?.[compare.columns.indexOf(data.columns[j])]?'changed':''}">${v===null?'<span class="null">missing</span>':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function renderData(){const d=state.dataset;let body=title('Dataset explorer','Every row has a story. Get to know yours.',button('Export CSV','download','export_csv',false,!d)+button('Import dataset','plus','import',true));if(!d)return body+noData();body+=`<div class="dataset-chips"><span class="tag purple">${icon('file')}${esc(d.name)}</span><span class="tag">${num(d.rows)} rows</span><span class="tag">${d.columns} columns</span><span class="tag">${num(d.missing_cells)} missing cells</span><span class="tag green">Version ${d.version}</span></div><div class="tabs"><button class="tab ${view.dataTab==='preview'?'active':''}" data-tab="preview">Data preview</button><button class="tab ${view.dataTab==='schema'?'active':''}" data-tab="schema">Column profiles</button><button class="tab ${view.dataTab==='versions'?'active':''}" data-tab="versions">Transformation history <span class="issue-count">${d.transformations.length}</span></button></div>`;
if(view.dataTab==='schema')return body+`<div class="panel"><div class="schema-grid">${d.fields.map(f=>`<div class="schema-card"><h3>${esc(f.name)}</h3><span class="tag purple">${esc(f.type)}</span><div class="column-stat"><span>Unique values</span><b>${num(f.unique)}</b></div><div class="column-stat"><span>Missing</span><b>${num(f.missing)} · ${(f.missing/d.rows*100).toFixed(1)}%</b></div></div>`).join('')}</div></div>`;
if(view.dataTab==='versions')return body+`<div class="panel">${panelHead('A transparent history','Your original data stays preserved.',button('Undo','undo','undo',false,!d.can_undo)+button('Redo','redo','redo',false,!d.can_redo))}<div class="panel-body"><div class="activity-row"><span class="activity-dot"></span><div><h3>Original CSV imported</h3><p>${esc(d.name)} · Version 0</p></div><span class="tag green">Preserved</span></div>${d.transformations.map((t,i)=>`<div class="activity-row"><span class="activity-dot"></span><div><h3>${esc(t.operation)}</h3><p>${esc(t.columns.join(', '))} · Version ${i+1}</p></div><span class="tag purple">Applied</span></div>`).join('')}</div></div>`;
const filtered={...d.preview,data:d.preview.data.filter(row=>!view.search||row.some(v=>String(v??'').toLowerCase().includes(view.search.toLowerCase())))};
return body+`<div class="panel"><div class="toolbar"><div class="search-wrap">${icon('search')}<input class="input" id="row-search" placeholder="Search preview rows…" value="${esc(view.search)}"></div><span class="push tag">Original file preserved</span>${pageButton('Analyze dataset','shield','analyzer')}</div><div class="table-scroll">${table(filtered,d.fields)}</div><div class="table-footer"><span>${filtered.data.length} preview rows of ${num(d.rows)} total</span><span>First 100 rows · Read-only preview</span></div></div>`;}
function renderAnalyzer(){const d=state.dataset;let body=title('A healthier dataset. A better start.','Understand what needs attention, with evidence you can inspect.',button('Analyze again','spark','analyze',true,!d));if(!d)return body+noData('Let’s understand your dataset.');body+=preprocessingGuide();const missing=state.issues.filter(i=>i.title==='Missing values').length;body+=`<div class="stats-grid">${stat('Total findings',num(state.issues.length),'Recommendations, never assumptions','shield')}${stat('Missing cells',num(d.missing_cells),`${missing} affected columns`,'table','orange')}${stat('Repeated rows',num(d.duplicates),'Review before removing','layers','blue')}${stat('Dataset version',String(d.version),'Original always preserved','history','green')}</div>`;const items=state.issues.map((issue,index)=>({issue,index})).filter(({issue})=>view.severity==='All findings'||issue.severity===view.severity);const selected=state.issues[view.issue];return body+`<div class="analyzer-grid"><section class="panel">${panelHead('Findings to review',`${state.issues.length} findings based on this dataset.`,`<select id="severity">${options(['All findings','High','Medium','Low'],view.severity)}</select>`)}<div class="issues-scroll">${items.map(({issue:i,index})=>`<button class="issue-card ${index===view.issue?'selected':''}" data-issue="${index}"><span class="issue-mark ${esc(i.severity)}">${icon(i.severity==='High'?'shield':'spark')}</span><div><h3>${esc(i.title)}</h3><p>${esc(i.columns.join(', ')||'Dataset-wide')} · ${num(i.count)} affected</p></div><span class="tag ${i.severity==='High'?'red':i.severity==='Medium'?'orange':'purple'}">${esc(i.severity)}</span></button>`).join('')||empty('check','Nothing in this filter','Choose another severity to view the remaining findings.','',true)}</div></section><section class="panel">${selected?`${panelHead(esc(selected.title),'Finding '+esc(selected.id),`<span class="tag purple">${esc(selected.status)}</span>`)}<div class="panel-body"><div class="detail-block"><h4>Why this matters</h4><p>${esc(selected.explanation)}</p></div><div class="detail-block"><h4>Detection method</h4><p>${esc(selected.method)}</p></div>${selected.evidence.length?`<div class="detail-block"><h4>Evidence · sample values or row indexes</h4><div class="evidence">${esc(JSON.stringify(selected.evidence))}</div></div>`:''}<div class="recommendation"><h4>A practical next step</h4><p>${esc(selected.recommendation)}</p></div><p class="hint">${esc(selected.risk)}</p></div>`:empty('check','No findings detected','The available rules found no issues. Domain review is still valuable.','',true)}</section></div><div class="panel" style="margin-top:20px">${panelHead('Make changes with confidence','Preview first. Apply only what makes sense. Undo when you need to.')}<div class="panel-body"><div class="chart-controls"><div class="form-field"><label>Transformation</label><select id="clean-operation">${options(['Fill missing','Remove duplicates','Trim whitespace','Lowercase labels','Convert to numeric','Drop columns'],'Trim whitespace')}</select></div><div class="form-field"><label>Column</label><select id="clean-column">${options(d.fields.map(f=>f.name),selected?.columns[0]||'')}</select></div>${button('Preview change','arrow','preview',true)}${button('Undo','undo','undo',false,!d.can_undo)}${button('Redo','redo','redo',false,!d.can_redo)}</div></div></div>`;}
function renderAnalytics(){const d=state.dataset;let body=title('Find the story in your data.','Choose your lens. Explore distributions, relationships, and missing values.');if(!d)return body+noData();body+=visualDashboard();const numericChart=['Histogram','Box plot','Scatter'].includes(view.chartType);const columns=d.fields.filter(f=>!numericChart||/int|float|double/i.test(f.type)).map(f=>f.name);if(!columns.includes(view.chartX))view.chartX=columns[0];if(!columns.includes(view.chartY))view.chartY=columns[Math.min(1,columns.length-1)];return body+`<div class="panel">${panelHead('Chart studio','Charts use the first 10,000 rows. The sample size is labeled on each chart.',`<span class="tag purple">${esc(d.name)}</span>`)}<div class="panel-body chart-controls"><div class="form-field"><label>Visualization</label><select id="chart-type">${options(['Histogram','Box plot','Scatter','Correlation','Missing values','Category frequencies'],view.chartType)}</select></div><div class="form-field"><label>X / column</label><select id="chart-x">${options(columns,view.chartX)}</select></div><div class="form-field"><label>Y / second column</label><select id="chart-y">${options(columns,view.chartY)}</select></div>${button('Create chart','chart','chart',true,!columns.length)}</div>${state.chart?`<img class="chart-image" alt="Actual dataset visualization" src="${state.chart}">`:`<div class="chart-placeholder">${empty('chart','A different perspective awaits','Choose columns and a chart type to visualize your actual data.','')}</div>`}</div>`;}
function configControls(){const d=state.dataset;return `<div class="form-field"><label>Target column</label><select data-config="target">${options(['',...d.fields.map(f=>f.name)],state.target)}</select></div><div class="form-field"><label>Algorithm</label><select data-config="algorithm">${options(state.algorithms,state.algorithm)}</select></div>`;}
function resultView(model){const metrics=Object.entries(model.metrics||{}).filter(([,v])=>typeof v==='number');const regression='RMSE' in model.metrics;return `<div class="panel-body"><div class="result-summary"><div><h3>${esc(model.metadata.algorithm)}</h3><p>${esc(model.metadata.protocol)} · ${num(model.metadata.test_rows)} test rows</p></div><span class="tag green">Completed</span></div><div class="metric-grid">${metrics.slice(0,6).map(([k,v])=>`<div class="metric"><small>${esc(k)}</small><b>${regression?v.toFixed(3):(v*100).toFixed(1)+'%'}</b><small>${regression?'Holdout estimate':'Weighted where applicable'}</small></div>`).join('')}</div>${model.metrics['Confusion matrix']?`<h3 style="font-size:11px">Confusion matrix</h3><p class="hint">Rows: actual · Columns: predicted · Labels: ${esc(model.metrics['Class labels'].join(', '))}</p><div class="matrix" style="grid-template-columns:repeat(${model.metrics['Confusion matrix'].length},1fr)">${model.metrics['Confusion matrix'].flat().map(v=>`<div style="background:rgba(116,96,231,${.05+v/Math.max(...model.metrics['Confusion matrix'].flat(),1)*.35})">${num(v)}</div>`).join('')}</div>`:''}<div class="dataset-chips"><span class="tag">${Number(model.metadata.seconds).toFixed(2)}s training</span><span class="tag">Seed ${model.metadata.seed}</span><span class="tag purple">Training-only preprocessing</span></div>${(model.metadata.warnings||[]).map(w=>`<div class="warning">${esc(w)}</div>`).join('')}</div>`;}
function renderModels(){const d=state.dataset;let body=title('Turn curiosity into an experiment.','Real models. Training-only preprocessing. Results you can inspect.');if(!d)return body+noData();return body+methodGuide()+`<div class="model-layout"><div><section class="panel">${panelHead('Experiment setup','Start with a question.')}<div class="config-body"><div class="form-field"><label>What do you want to predict?</label><select id="task-choice">${options(['classification','regression'],state.guidance?.task)}</select></div>${configControls()}<div class="model-option">${icon('shield')}Leakage-safe preprocessing</div><div class="column-stat"><span>Holdout split</span><b>75% / 25%</b></div><div class="column-stat"><span>Random seed</span><b>42</b></div><div class="column-stat"><span>Processing</span><b>Local CPU</b></div>${button(state.busy?'Training…':'Train & evaluate','play','train',true,state.busy,'style="width:100%;margin-top:15px"')}<div style="margin-top:9px">${button('Compare same-task models','layers','compare',false,state.busy,'style="width:100%"')}</div><p class="hint">Comparison reuses the same split. Reserve independent final data after choosing a model.</p></div></section><section class="panel" style="margin-top:17px">${panelHead('Explore without a target','Numeric features only.')}<div class="config-body"><select id="cluster-algorithm" class="full-width">${options(['K-Means','DBSCAN','Hierarchical','PCA'],'K-Means')}</select>${button('Run exploration','spark','cluster',false,state.busy,'style="width:100%;margin-top:12px"')}<p class="hint">Full-dataset exploration. Results appear in Experiment History.</p></div></section></div><section class="panel">${panelHead('Evaluation results','Metrics from your actual holdout data.',state.model?`<span class="tag green">Model trained</span>`:state.comparison.length?'<span class="tag green">Comparison complete</span>':'<span class="tag">Awaiting an experiment</span>')}${state.model?resultView(state.model):state.comparison.length?comparisonView():empty('brain','Let’s see what your data can do.','Choose your target and algorithm, then run your first experiment. Your results will appear right here.','')}</section></div>`;}
function metricSummary(result){const m=result.metrics||{};return Object.entries(m).filter(([,v])=>typeof v==='number').slice(0,3).map(([k,v])=>`${esc(k)} <b>${Number(v).toFixed(3)}</b>`).join(' · ')||'Exploratory projection / clustering';}
function comparisonView(){const results=state.comparison;const regression=results[0]?.result?.metrics?.RMSE!==undefined;const columns=regression?['MAE','RMSE','R2']:['Accuracy','F1 (weighted)','ROC-AUC'];return `<div class="panel-body">${comparisonReason()}<div class="result-summary"><div><h3>${results.length} models. One consistent protocol.</h3><p>Same holdout split and training-only preprocessing.</p></div><span class="tag green">Comparison complete</span></div><div class="table-scroll"><table><thead><tr><th>ALGORITHM</th>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}<th>TRAINING</th></tr></thead><tbody>${results.map(e=>`<tr><td>${esc(e.algorithm)}</td>${columns.map(c=>`<td>${typeof e.result.metrics[c]==='number'?(regression?e.result.metrics[c].toFixed(3):(e.result.metrics[c]*100).toFixed(1)+'%'):'—'}</td>`).join('')}<td>${Number(e.result.metadata.seconds).toFixed(2)}s</td></tr>`).join('')}</tbody></table></div><div class="warning">This comparison is exploratory. Repeated selection on the same holdout biases the estimate. Use independent final data after choosing a model. No winner is selected automatically.</div>${pageButton('Inspect individual experiments','history','history')}</div>`;}
function renderHistory(){let body=title('Every experiment is a step forward.','Your local experiment journal. Real runs, preserved results.',button('New experiment','plus','go_models',true));if(!state.experiments.length)return body+`<div class="panel">${empty('history','Your experiment journal starts here.','Train a model or explore clustering to create your first entry.',pageButton('Open Model Lab','brain','models',true))}</div>`;return body+`<div class="panel">${panelHead('Experiment journal',`${num(state.experiment_count)} experiments stored on this computer.`,`<span class="tag green">Local SQLite</span>`)}<div class="table-scroll"><table><thead><tr><th>EXPERIMENT</th><th>CREATED (UTC)</th><th>RESULTS</th><th>STATUS</th><th></th></tr></thead><tbody>${state.experiments.map((e,i)=>`<tr><td><b>${esc(e.algorithm)}</b><p style="font-size:9px">${esc(e.result.metadata?.target||'Numeric exploration')}</p></td><td>${esc(e.created)}</td><td class="history-code">${metricSummary(e.result)}</td><td><span class="tag green">Completed</span></td><td><button class="text-link" data-experiment="${i}">Inspect ↗</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Showing the latest ${state.experiments.length} experiments</span><span>All results stay on this device</span></div></div>`;}
function renderPredictions(){return title('From an experiment to an answer.','Use your current trained pipeline on compatible new data.')+`<div class="panel">${panelHead('Your session model','Models currently remain available for this application session only.',state.model?'<span class="tag green">Ready to predict</span>':'<span class="tag">No session model</span>')}${state.model?`<div class="panel-body"><div class="file-card"><span class="stat-icon">${icon('brain')}</span><div class="file-meta"><h3>${esc(state.model.metadata.algorithm)}</h3><p>Target: ${esc(state.model.metadata.target)} · ${state.model.metadata.features.length} input features</p></div>${button('Predict a new CSV','arrow','predict',true)}</div><h3 style="margin:25px 0 12px;font-size:12px">Expected input columns</h3><div class="dataset-chips">${state.model.metadata.features.map(f=>`<span class="tag purple">${esc(f)}</span>`).join('')}</div><div class="warning">Your input CSV must contain exactly these feature columns. Leave out the target column. Missing or unexpected columns are rejected.</div></div>`:empty('box','A trained model belongs here.','Train a model in Model Lab, then return here to make predictions from a new CSV.',pageButton('Go to Model Lab','arrow','models',true))}</div>`;}
function renderReports(){return title('Make your work easy to share.','Export what you learned, with actual findings and evaluation results.',pageButton('Reproducible Research Pack','code','researchpack',true))+`<div class="report-grid">${[['report','Experiment report','A self-contained HTML document with your dataset overview, quality findings, transformations and current model metrics.','Export HTML','report'],['database','Cleaned dataset','Save the current version as a separate CSV. Your original file stays exactly where it is.','Export CSV','export_csv'],['history','Transformation log','Keep a transparent JSON record of the transformations applied to the active dataset version.','Export log','export_log']].map(([ic,h,p,b,a])=>`<section class="panel report-card"><span class="stat-icon">${icon(ic)}</span><h2>${h}</h2><p>${p}</p>${button(b,'download',a,false,!state.dataset)}</section>`).join('')}</div><section class="panel" style="margin-top:22px">${panelHead('Keep the whole workspace together','Save a project to reopen your workflow and dataset transformations.')}<div class="panel-body"><p class="paragraph">A project references your original CSV and records its fingerprint, import settings, cleaning steps, workflow, and model settings. Keep the original source file available when reopening it.</p><div class="actions" style="margin-top:20px">${button('Save project','folder','save',true,!state.dataset)}${button('Open project','folder','open')}</div></div></section>`;}
function renderSettings(){return title('A workspace that’s truly yours.','Local-first by design. Simple, transparent, and in your control.')+`<section class="panel">${panelHead('Workspace & privacy')}<div class="settings-list"><div class="settings-row"><div><h3>Your data stays here.</h3><p>CSV files, model training, charts and reports are processed on your computer. No telemetry, cloud authentication, API keys, or runtime downloads. The embedded interface blocks external network requests.</p></div><span class="tag green">Offline</span></div><div class="settings-row"><div><h3>Local storage</h3><p><code>${esc(state.storage)}</code></p></div><span class="tag">SQLite</span></div><div class="settings-row"><div><h3>Keyboard shortcuts</h3><p>Ctrl + I · Import dataset<br>Ctrl + O · Open project<br>Ctrl + S · Save project<br>Esc · Dismiss preview</p></div>${icon('code')}</div><div class="settings-row"><div><h3>ML Studio ${esc(state.version)}</h3><p>Modern embedded desktop interface. Core models use reproducible holdout evaluation; inspect the validation protocol and warnings before interpreting results.</p></div><span class="tag purple">Development release</span></div><div class="settings-row"><div><h3>What’s still growing</h3><p>PyTorch training, persistent model bundles, general-purpose PDF experiment reports and the full workflow node catalog are not yet available. See DEVELOPMENT_STATUS.md for the detailed implementation status.</p></div></div></div></section>`;}
function renderDeep(){return title('Room for deeper experiments.','A dedicated space for local neural networks, once the training engine is ready.')+`<section class="panel">${empty('layers','Deep Learning Lab is still in development.','The PyTorch engine is not implemented in this release. You can train and evaluate eleven traditional algorithms in Model Lab.',pageButton('Explore Model Lab','arrow','models',true))}</section>`;}
function renderWorkflow(){const graph=state.workflow;const selected=graph.nodes[view.selectedNode];return title('Ideas connect here.','Drag nodes onto the canvas. Connect an output port to a compatible input.',button('Save project','folder','save',false,!state.dataset)+button('Run workflow','play','run_workflow',true,!state.dataset||state.busy))+`<div class="panel"><div class="toolbar">${button('Starter pipeline','plus','starter')}<span class="tag">${Object.keys(graph.nodes).length} nodes</span><span class="push"></span>${button('Validate','check','validate')}${button('Undo','undo','graph_undo',false,!view.graphHistory.length)}<button class="icon-button" data-action="zoom_out" title="Zoom out">${icon('minus')}</button><span class="subtle" style="font-size:10px">${Math.round(view.zoom*100)}%</span><button class="icon-button" data-action="zoom_in" title="Zoom in">${icon('plus')}</button><button class="icon-button" data-action="fit" title="Reset zoom">${icon('fit')}</button></div><div class="workflow-shell"><aside class="node-library"><h3>NODE LIBRARY</h3><p class="hint" style="margin:0">Drag a node to the canvas.</p><div class="library-category">DATA</div><div class="library-node" draggable="true" data-kind="Dataset">${icon('database')}Dataset</div><div class="library-category">PREPROCESSING</div><div class="library-node" draggable="true" data-kind="Remove duplicates">${icon('filter')}Remove duplicates</div><div class="library-category">MODELING</div><div class="library-node" draggable="true" data-kind="Train model">${icon('brain')}Train model</div><p class="hint" style="margin-top:25px">Imputation, encoding, and scaling are fitted inside the model’s training pipeline.</p><p class="hint">More node types are under development.</p></aside><div class="canvas-host"><div class="workflow-surface" style="transform:scale(${view.zoom})"><svg><defs><marker id="edge-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="m0 0 7 3.5L0 7" fill="#b3a3d6"/></marker></defs>${graph.edges.map(([a,b])=>edgePath(graph.nodes[a],graph.nodes[b])).join('')}</svg>${Object.entries(graph.nodes).map(([id,n])=>`<div class="workflow-node ${id===view.selectedNode?'selected':''}" data-node="${id}" style="left:${n.position[0]}px;top:${n.position[1]}px"><span class="stat-icon">${icon(n.type==='Dataset'?'database':n.type==='Train model'?'brain':'filter')}</span><h3>${esc(n.type)}</h3><small>${n.type==='Train model'?esc(state.algorithm):n.type==='Dataset'?'Active dataset':'Review duplicate observations'}</small>${n.type!=='Dataset'?`<button class="port input" data-port="input" data-node-id="${id}" title="Data input"></button>`:''}<button class="port output ${view.connecting===id?'connecting':''}" data-port="output" data-node-id="${id}" title="${n.type==='Train model'?'Result output':'Data output'}"></button></div>`).join('')}</div>${Object.keys(graph.nodes).length?'':`<div class="canvas-empty"><h3>A blank canvas. Plenty of possibilities.</h3><p>Drag a node from the library, or start with a simple pipeline.</p></div>`}</div><aside class="properties"><h3>NODE PROPERTIES</h3>${selected?`<span class="tag purple">${esc(selected.type)}</span>${selected.type==='Train model'?`<div style="margin-top:22px">${configControls()}</div>`:selected.type==='Dataset'?`<p class="hint">Uses your active dataset: ${esc(state.dataset?.name||'No dataset imported')}.</p>`:`<p class="hint">Removes exactly repeated rows. Repeated observations may be valid; review before running.</p>`}<div class="actions" style="margin-top:25px">${button('Delete node','trash','delete_node',false,false,'class="small"')}</div>${button('Disconnect input','undo','disconnect',false,!graph.edges.some(([,b])=>b===view.selectedNode),'style="margin-top:10px;font-size:10px"')}`:`<p class="hint">Select a node to inspect its settings.</p><div class="empty-progress">Data → preprocessing → model</div><p class="hint">Connect the small circles on each node. Blue-purple paths carry real data between operations.</p>`}</aside></div><div class="workflow-log"><b>EXECUTION LOG</b><span>${esc(state.events.at(-1)||'Ready. Add nodes to start building your workflow.')}</span></div></div>`;}
function edgePath(a,b){if(!a||!b)return '';const x1=a.position[0]+172,y1=a.position[1]+48,x2=b.position[0],y2=b.position[1]+48;const bend=Math.max(45,Math.abs(x2-x1)/2);return `<path d="M${x1} ${y1}C${x1+bend} ${y1},${x2-bend} ${y2},${x2} ${y2}" stroke="#b3a3d6" stroke-width="1.7" fill="none" marker-end="url(#edge-arrow)"/>`;}
function renderModal(){const root=document.querySelector('#modal-root');if(state.preview){const p=state.preview;root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Transformation preview"><div class="modal-header"><div><span class="not-available">REVIEW BEFORE APPLYING</span><h2>${esc(p.operation.operation)}</h2><p>${esc(p.operation.columns.join(', '))} · ${num(p.before_rows)} → ${num(p.after_rows)} rows</p></div><button class="icon-button" data-action="cancel_preview" title="Close preview">${icon('close')}</button></div><div class="modal-body"><div class="warning">This preview shows the first 8 rows. Changes create a new version and preserve your original. Exploratory imputation must be undone before model evaluation.</div><div class="preview-grid"><div><div class="preview-heading">Before<span class="tag">Current version</span></div><div class="preview-table">${table(p.before,[],8)}</div></div><div><div class="preview-heading">After<span class="tag purple">Proposed version</span></div><div class="preview-table">${table(p.after,[],8,p.before)}</div></div></div></div><div class="modal-footer"><span>Reversible with Undo after applying.</span><div class="actions">${button('Keep current data','','cancel_preview')}${button('Apply transformation','check','apply_preview',true)}</div></div></section></div>`;}else if(view.experiment!==null){const e=state.experiments[view.experiment];root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Experiment details"><div class="modal-header"><div><h2>${esc(e.algorithm)}</h2><p>${esc(e.created)} UTC · Stored experiment</p></div><button class="icon-button" data-action="close_experiment" title="Close">${icon('close')}</button></div><div class="modal-body">${e.result.research?researchHistoryDetail(e.result.research):e.result.metadata?resultView(e.result):`<div class="evidence" style="max-height:500px;overflow:auto">${esc(JSON.stringify(e.result,null,2))}</div>`}</div></section></div>`;}else root.innerHTML='';}
function mutateGraph(callback,history=true){const next=structuredClone(state.workflow);if(history)view.graphHistory.push(structuredClone(state.workflow));callback(next);state.workflow=next;cmd('workflow',next);render();}
function doAction(action){if(action.startsWith('research_')&&researchAction(action))return;const value=id=>document.getElementById(id)?.value;if(action.startsWith('go_'))return navigate(action.slice(3));if(action==='import_advanced')return cmd('import_advanced');if(action==='refresh_visuals')return cmd('visuals',{x:value('auto-x'),y:value('auto-y'),category:value('auto-category')});if(action==='preview')return cmd('preview',{operation:value('clean-operation'),column:value('clean-column')});if(action==='chart'){view.chartType=value('chart-type');view.chartX=value('chart-x');view.chartY=value('chart-y');return cmd('chart',{type:view.chartType,x:view.chartX,y:view.chartY});}if(action==='cluster')return cmd('cluster',{algorithm:value('cluster-algorithm')});if(action==='starter'){mutateGraph(g=>{const start=Math.max(0,...Object.keys(g.nodes).map(Number))+1;g.nodes[String(start)]={type:'Dataset',position:[35,90]};g.nodes[String(start+1)]={type:'Remove duplicates',position:[245,90]};g.nodes[String(start+2)]={type:'Train model',position:[455,90]};g.edges.push([String(start),String(start+1)],[String(start+1),String(start+2)]);});return;}if(action==='delete_node'){mutateGraph(g=>{delete g.nodes[view.selectedNode];g.edges=g.edges.filter(([a,b])=>a!==view.selectedNode&&b!==view.selectedNode);});view.selectedNode=null;return;}if(action==='disconnect')return mutateGraph(g=>{g.edges=g.edges.filter(([,b])=>b!==view.selectedNode);});if(action==='graph_undo'){const previous=view.graphHistory.pop();if(previous){state.workflow=previous;cmd('workflow',previous);render();}return;}if(['zoom_in','zoom_out','fit'].includes(action)){if(action==='fit'){const host=document.querySelector('.canvas-host');const nodes=Object.values(state.workflow.nodes);const width=Math.max(300,...nodes.map(n=>n.position[0]+210));const height=Math.max(250,...nodes.map(n=>n.position[1]+140));view.zoom=Math.max(.3,Math.min(1,(host.clientWidth-20)/width,(host.clientHeight-20)/height));}else{view.zoom=Math.max(.3,Math.min(1.8,view.zoom+(action==='zoom_in'?.1:-.1)));}render();return;}if(action==='close_experiment'){view.experiment=null;renderModal();return;}cmd(action);}
document.addEventListener('click',event=>{const suggested=event.target.closest('[data-suggestion]');if(suggested){const step=state.guidance.steps[Number(suggested.dataset.suggestion)];cmd('preview',{operation:step.operation,column:step.columns[0]||state.dataset.fields[0].name});return;}const page=event.target.closest('[data-page]');if(page){navigate(page.dataset.page);return;}const action=event.target.closest('[data-action]');if(action&&!action.disabled){doAction(action.dataset.action);return;}const issue=event.target.closest('[data-issue]');if(issue){view.issue=Number(issue.dataset.issue);render();return;}const tab=event.target.closest('[data-tab]');if(tab){view.dataTab=tab.dataset.tab;render();return;}const experiment=event.target.closest('[data-experiment]');if(experiment){view.experiment=Number(experiment.dataset.experiment);renderModal();return;}const port=event.target.closest('[data-port]');if(port){const id=port.dataset.nodeId;if(port.dataset.port==='output'){view.connecting=id;render();}else if(view.connecting){const source=view.connecting;view.connecting=null;if(source===id||state.workflow.nodes[source].type==='Train model')return toast('Connect a data output to another node’s input.','error');if(state.workflow.edges.some(([,b])=>b===id))return toast('This input already has a connection. Disconnect it first.','error');mutateGraph(g=>g.edges.push([source,id]));}return;}const node=event.target.closest('[data-node]');if(node){view.selectedNode=node.dataset.node;render();}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.config){cmd('configure',{[el.dataset.config]:el.value});return;}if(el.id==='task-choice'){cmd('task',{task:el.value});return;}if(el.id==='severity'){view.severity=el.value;render();}if(el.id==='chart-type')view.chartType=el.value;if(el.id==='chart-x')view.chartX=el.value;if(el.id==='chart-y')view.chartY=el.value;});
document.addEventListener('input',event=>{if(event.target.id==='row-search'){const position=event.target.selectionStart;view.search=event.target.value;render();const input=document.getElementById('row-search');input.focus();input.setSelectionRange(position,position);}});
document.addEventListener('keydown',event=>{if(event.ctrlKey&&['i','o','s'].includes(event.key.toLowerCase())){event.preventDefault();cmd({i:'import',o:'open',s:'save'}[event.key.toLowerCase()]);}if(event.key==='Escape'){if(state?.preview)cmd('cancel_preview');view.experiment=null;view.connecting=null;renderModal();}if(event.key==='Delete'&&view.page==='workflow'&&view.selectedNode&&!['INPUT','SELECT'].includes(event.target.tagName))doAction('delete_node');});
document.addEventListener('dragstart',event=>{const item=event.target.closest('[data-kind]');if(item){event.dataTransfer.setData('text/plain',item.dataset.kind);event.dataTransfer.effectAllowed='copy';}});
document.addEventListener('dragover',event=>{if(event.target.closest('.canvas-host')){event.preventDefault();event.dataTransfer.dropEffect='copy';}});
document.addEventListener('drop',event=>{const host=event.target.closest('.canvas-host');if(!host)return;event.preventDefault();const kind=event.dataTransfer.getData('text/plain');if(!['Dataset','Remove duplicates','Train model'].includes(kind))return;const rect=host.getBoundingClientRect();mutateGraph(g=>{const id=String(Math.max(0,...Object.keys(g.nodes).map(Number))+1);g.nodes[id]={type:kind,position:[Math.max(15,(event.clientX-rect.left+host.scrollLeft)/view.zoom),Math.max(15,(event.clientY-rect.top+host.scrollTop)/view.zoom)]};view.selectedNode=id;});});
let dragging=null;
document.addEventListener('pointerdown',event=>{const el=event.target.closest('.workflow-node');if(!el||event.target.closest('button'))return;dragging={el,id:el.dataset.node,x:event.clientX,y:event.clientY,start:[...state.workflow.nodes[el.dataset.node].position],moved:false};el.setPointerCapture(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!dragging)return;const dx=(event.clientX-dragging.x)/view.zoom,dy=(event.clientY-dragging.y)/view.zoom;if(Math.abs(dx)+Math.abs(dy)>3)dragging.moved=true;const node=state.workflow.nodes[dragging.id];node.position=[Math.max(10,dragging.start[0]+dx),Math.max(10,dragging.start[1]+dy)];dragging.el.style.left=node.position[0]+'px';dragging.el.style.top=node.position[1]+'px';const svg=document.querySelector('.workflow-surface>svg');svg.querySelectorAll(':scope>path').forEach(p=>p.remove());svg.insertAdjacentHTML('beforeend',state.workflow.edges.map(([a,b])=>edgePath(state.workflow.nodes[a],state.workflow.nodes[b])).join(''));});
document.addEventListener('pointerup',()=>{if(!dragging)return;const drag=dragging;dragging=null;if(drag.moved){const previous=structuredClone(state.workflow);previous.nodes[drag.id].position=drag.start;view.graphHistory.push(previous);view.selectedNode=drag.id;cmd('workflow',state.workflow);}});
function connectStudio(){new QWebChannel(qt.webChannelTransport,channel=>{bridge=channel.objects.studio;bridge.stateChanged.connect(payload=>{state=JSON.parse(payload);if(state.dataset&&state.dataset.source!==lastSource){lastSource=state.dataset.source;view.page='home';view.search='';view.experiment=null;view.issue=0;}window.appState=state;render();});bridge.notice.connect(payload=>{const n=JSON.parse(payload);toast(n.message,n.kind);});cmd('ready');});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',connectStudio,{once:true});else connectStudio();
// Stable in-process surface used by native integration smoke tests.
window.studioUI={navigate,command:cmd,get state(){return state;},get page(){return view.page;}};
